	// Pipeline skeleton (design freeze 2026-10-24): the ONE slot registry (VP-V/core/SlotRegistry.h). It
	// decides which slots run and in which order: the entrance stage list (RunEntrance) and the
	// output hooks follow it. Rebuilt from the settings on every settings apply.
	PipelineSlots::Registry pipelineSlots;
	std::string pipelineStateLogged;
	void UpdatePipelineSlots(const RendererSettings& settings)
	{
		PipelineSlots::Registry next;
		if (settings.pipelineOriginalPathway)
			next.ApplyOriginalPathway();
		// Every refused value is visible (owner rule: no silent fallbacks), never log-only.
		std::string problems = settings.pipelineSettingsProblems;
		std::string token;
		auto flush = [&]()
		{
			if (token.empty())
				return;
			const PipelineSlots::Id id = PipelineSlots::FromName(token.c_str());
			if (id == PipelineSlots::Id::Count)
				problems += "pipeline_slots_off: unknown slot '" + token + "'; ";
			else if (!PipelineSlots::SwitchHonoured(id))
				problems += "pipeline_slots_off: " + token + " has no slot switch yet; ";
			else
				next.SetEnabled(id, false);
			token.clear();
		};
		for (char ch : settings.pipelineSlotsOff)
		{
			if (ch == ',' || ch == ' ' || ch == ';' || ch == '\t')
				flush();
			else
				token += ch;
		}
		flush();
		if (!problems.empty())
		{
			problems.resize(problems.size() - 2);   // the last "; "
			EngageFallback("pipeline settings", "ignored: " + problems);
		}
		else
			ReleaseFallback("pipeline settings");
		std::string reason;
		if (!settings.pipelineOriginalPathway && !next.SetOrderByNames(settings.pipelineOrder, &reason))
			EngageFallback("pipeline order", "designed order kept: " + reason);   // an invalid order never runs
		else
			ReleaseFallback("pipeline order");
		next.SetEntranceOnce(settings.pipelineEntranceOnce && !settings.pipelineOriginalPathway);   // B3: consumers after the entrance
		(void)next.ActiveEntrance();   // warm the kept list here, so the render thread only reads it
		pipelineSlots = next;
		entranceCache.Invalidate();
		entranceRing.Invalidate();
		std::string state = settings.pipelineOriginalPathway ? "Original pathway (every VP addition off)" :
			pipelineSlots.IsDefaultOrder() ? "designed order" : "custom order";
		std::string entrance;
		for (PipelineSlots::Id id : pipelineSlots.ActiveEntrance())
			entrance += (entrance.empty() ? "" : " > ") + std::string(PipelineSlots::Get(id).name);
		state += "; entrance: " + (entrance.empty() ? std::string("none") : entrance);
		state += settings.pipelineEntranceOnce && !settings.pipelineOriginalPathway ?
			"; entrance once (B3) on: motion pictures from the processed A and B" : "; entrance once (B3) off";
		// entrance_gpu_drain: visible while it is on (Ctrl+I "engaged" line, Config status), never silent.
		// Listed only when it can act: on, not the Original pathway, and scaling.rebase runs.
		EntranceGpuDrain::Mode drainMode = EntranceGpuDrain::Mode::Off;
		EntranceGpuDrain::Parse(settings.entranceGpuDrain, drainMode);
		if (drainMode != EntranceGpuDrain::Mode::Off && !settings.pipelineOriginalPathway &&
			pipelineSlots.Runs(PipelineSlots::Id::ScalingRebase))
		{
			state += std::string("; entrance GPU drain: ") + EntranceGpuDrain::Name(drainMode);
			EngageFallback("entrance GPU drain", EntranceGpuDrain::StatusReason(drainMode));   // a mode change updates the reason
		}
		else
			ReleaseFallback("entrance GPU drain");
		if (!settings.pipelineEntranceOnce || settings.pipelineOriginalPathway)
		{
			entranceOnceNote.clear();
			ReleaseFallback("entrance once");
			ReleaseFallback("entrance once fill");
			// Its textures are freed on the render thread (RunMainEntrance), never from here.
		}
		if (state != pipelineStateLogged)
		{
			pipelineStateLogged = state;
			DebugLog::Log("Pipeline: %s", state.c_str());
		}
	}
	// r6 fix 4: render-ahead only inside the fixed delay budget (RenderAhead::FitDelayBudget).
	// render_ahead on but its lead not given back by the queue: off for this source (the plain
	// per-refresh path, exactly as render_ahead off), listed under "Fallbacks engaged".
	bool renderAheadBudgetVeto = false;
	size_t renderAheadBudgetCredit = 0;   // the frames the budget lets the queue give back
	bool RenderAheadActive() const { return activeSettings.renderAhead && !renderAheadBudgetVeto; }
	void UpdateRenderAheadBudget(double captureRateHz)
	{
		if (!activeSettings.renderAhead)
		{
			renderAheadBudgetVeto = false;
			renderAheadBudgetCredit = 0;
			ReleaseFallback("render-ahead");
			return;
		}
		double displayHz = renderLoadDisplayRefreshHz.load(std::memory_order_acquire);
		if (!(displayHz > 0.0))
			displayHz = presentationTelemetry.Snapshot().measuredDisplayHz;
		if (!(captureRateHz > 0.0) || !(displayHz > 0.0))
			return;   // rates not known yet: the last decision stands
		const size_t queueFrames = earlyUploadQueueTarget.load(std::memory_order_acquire);
		const RenderAhead::BudgetDecision d = RenderAhead::FitDelayBudget(1.0 / captureRateHz, 1.0 / displayHz,
			queueFrames, activeSettings.renderAheadQueueCredit);
		renderAheadBudgetCredit = d.fits ? d.creditFrames : 0;
		const bool veto = !d.fits;
		if (veto != renderAheadBudgetVeto)
		{
			DebugLog::Log("Render-ahead: %s - lead %.1f ms, queue %zu frames (%.1f ms budget), with render-ahead %.1f ms, "
				"credit %zu frames (%s)", veto ? "OFF, outside the delay budget" : "on, inside the delay budget",
				d.leadMs, queueFrames, d.budgetMs, d.totalMs, d.creditFrames, d.reason);
			if (veto)
			{
				RenderAheadBreak();
				renderAheadCredit.Reset();
				renderAheadCreditFrames.store(0, std::memory_order_release);
			}
			else
				renderAheadEpoch.Invalidate();   // as render_ahead switched on: the gate starts again
			renderAheadBudgetVeto = veto;
		}
		if (veto)
		{
			char why[200];
			snprintf(why, sizeof(why), "off: its %.0f ms lead does not fit the %.0f ms delay budget; %s",
				d.leadMs, d.budgetMs, d.reason);
			EngageFallback("render-ahead", why);
		}
		else
			ReleaseFallback("render-ahead");
	}
