void LibplaceboVideoRenderer::Start()
{
	if (!m_impl || m_state.load(std::memory_order_acquire) != RendererState::RENDERSTATE_READY)
		throw std::runtime_error("libplacebo renderer is not ready");

	BeginQueueGeneration("start", true);
	m_renderThread = std::thread(&LibplaceboVideoRenderer::RenderLoop, this);
}


void LibplaceboVideoRenderer::Stop()
{
	StopInternal({});
}


void LibplaceboVideoRenderer::StopWithIngressDrain(
	const std::function<void()>& drainAfterGraphStop)
{
	// A cold libplacebo compile cannot be interrupted safely. Keep its join and
	// the ingress drain away from the MFC thread; completion is reported through
	// the existing posted renderer-state callback.
	bool expected = false;
	if (!m_stopWorkerStarted.compare_exchange_strong(
		expected, true, std::memory_order_acq_rel))
	{
		return;
	}
	// Publish stop intent before returning to the GUI. The render thread can no
	// longer report FAILED in the scheduling gap before the worker starts.
	{
		std::lock_guard<std::mutex> guard(m_queueMutex);
		m_stopRequested = true;
	}
	m_queueChanged.notify_all();
	m_fileSlotGate.Cancel();   // ABI 37: a waiting file source returns false
	try
	{
		m_stopWorker = std::thread([this, drainAfterGraphStop]()
			{
				StopInternal(drainAfterGraphStop);
			});
	}
	catch (...)
	{
		m_stopWorkerStarted.store(false, std::memory_order_release);
		throw;
	}
}


void LibplaceboVideoRenderer::StopInternal(
	const std::function<void()>& drainAfterGraphStop)
{
	{
		std::lock_guard<std::mutex> guard(m_queueMutex);
		m_stopRequested = true;
	}
	m_queueChanged.notify_all();
	m_fileSlotGate.Cancel();   // ABI 37: a waiting file source returns false
	if (m_renderThread.joinable())
		m_renderThread.join();
	if (m_conversionThread.joinable())
		m_conversionThread.join();
	ClearQueue("renderer stop");
	if (drainAfterGraphStop)
		drainAfterGraphStop();
	SetState(RendererState::RENDERSTATE_STOPPED);
}


void LibplaceboVideoRenderer::Retire() noexcept
{
	try
	{
		if (m_stopWorker.joinable())
			m_stopWorker.join();
		{
			std::lock_guard<std::mutex> guard(m_queueMutex);
			m_stopRequested = true;
		}
		m_queueChanged.notify_all();
		m_fileSlotGate.Cancel();   // ABI 37: a waiting file source returns false
		// Do not call Stop(): this can run after the GUI has already processed
		// the stopped-state notification, and a second callback could be applied
		// to the replacement renderer. Join directly before releasing the
		// swapchain, so no render or present can still use it.
		if (m_renderThread.joinable())
		{
			m_renderThread.join();
		}
		if (m_conversionThread.joinable())
			m_conversionThread.join();
		ClearQueue("renderer retirement");
		bool blackPresented = false;
		bool externalStateRestored = true;
		if (m_impl)
		{
			std::lock_guard<std::mutex> renderGuard(m_impl->renderMutex);
			if (!m_impl->outputResourcesRetired)
				blackPresented = m_impl->PresentBlackFrame();
			externalStateRestored = m_impl->RetireOutput();
		}
		DebugLog::Log(
			"VP Renderer retirement: terminal black present=%d "
			"before swapchain release external_state=%s",
			blackPresented ? 1 : 0,
			externalStateRestored ? "restored" : "pending");
		m_retirementSucceeded.store(
			externalStateRestored, std::memory_order_release);
		if (externalStateRestored)
			m_impl.reset();
		m_hasPresentedLiveFrame.store(false, std::memory_order_release);
		DebugLog::Log(
			"VP Renderer retired: render thread stopped and presentation "
			"swapchain released external_state=%s",
			externalStateRestored ? "restored" : "pending-retry");
	}
	catch (const std::exception& error)
	{
		m_retirementSucceeded.store(false, std::memory_order_release);
		DebugLog::Log("VP Renderer retirement failed: %s", error.what());
	}
	catch (...)
	{
		m_retirementSucceeded.store(false, std::memory_order_release);
		DebugLog::Log("VP Renderer retirement failed with an unknown exception");
	}
}


bool LibplaceboVideoRenderer::FinalizeRetirementForShutdown() noexcept
{
	try
	{
		if (!m_impl)
			return true;
		bool releaseSafe = false;
		{
			std::lock_guard<std::mutex> renderGuard(m_impl->renderMutex);
			releaseSafe = m_impl->FinalizeRetirementForShutdown();
		}
		if (!releaseSafe)
			return false;
		// Destroy the implementation on the retirement worker now that all
		// renderer-local resources are gone and external retry ownership has been
		// explicitly abandoned for process shutdown. Any transient shared_ptr
		// released later has a nonblocking renderer destructor.
		m_impl.reset();
		return true;
	}
	catch (const std::exception& error)
	{
		DebugLog::Log(
			"VP Renderer shutdown finalization failed: %s", error.what());
		return false;
	}
	catch (...)
	{
		DebugLog::Log(
			"VP Renderer shutdown finalization failed with an unknown exception");
		return false;
	}
}


void LibplaceboVideoRenderer::Reset()
{
	// Queue invalidation is CPU-side state and must never wait for an in-flight
	// libplacebo compile. In particular, HDMI re-sync can arrive on the UI
	// thread while pl_render_image is building a new program.
	if (m_impl)
	{
		m_impl->subtitlePreviewState.ResetForSourceChange();
		// Source-derived presentation authority belongs to the discarded queue
		// generation. Consume this request at the next render-thread safe point;
		// do not take the render lock or flush libplacebo here. This must precede
		// opening the new generation, so its first admitted frame cannot present
		// with geometry from the discarded generation.
		m_impl->RequestPresentationStateReset();
		m_impl->RequestMotionInvalidate(MotionValidity::Cause::Resync);
		m_impl->motionLastStateReset.store(true, std::memory_order_release);
		// Stage 12: a resync or source change - the resolution evidence belongs to what came before.
		m_impl->sourceMonitor.Discontinuity("resync or source change");
	}
	m_pulldownResetRequested.store(true, std::memory_order_release);
	BeginQueueGeneration("renderer reset");
	if (m_impl)
	{
		// HDMI and presentation resets retain the same renderer/device. Flushing
		// here throws away compiled programs and turns the next frame into a long
		// blocking shader build. libplacebo reconciles changed frame/target data
		// in pl_render_image, so retain the cache across this reset.
		std::unique_lock<std::mutex> guard(
			m_impl->renderMutex, std::try_to_lock);
		if (guard.owns_lock() && m_impl->renderer)
		{
			m_impl->LogResolvedRenderOptions(
				"renderer reset (including HDMI re-sync)");
		}
		else
		{
			DebugLog::Log(
				"libplacebo renderer reset: render busy; resolved-state log deferred");
		}
	}
	m_frameCounter.store(0, std::memory_order_relaxed);
	m_sceneDetectorGeneration.fetch_add(1, std::memory_order_acq_rel);
	ResetFrameRateAndPPM();
	DebugLog::Log("libplacebo renderer reset: new queue generation; shader cache retained");
}


void LibplaceboVideoRenderer::ResetLiveQueue()
{
	// This may be called from UI/profile application paths. It only advances
	// queue state, so waiting for the GPU render/compile lock is unnecessary.
	// It nevertheless discards source frames, so the next generation must not
	// reuse source-derived crop/presentation authority from the old queue.
	if (m_impl)
	{
		m_impl->RequestPresentationStateReset();
		// The discarded frames break the sequence: no pair or history across it.
		m_impl->RequestMotionInvalidate(MotionValidity::Cause::QueueReset);
		// The last frame's video state is kept: QueueReset does not release, so a format
		// change across this reset still releases (SourceFormatChange).
		m_impl->sourceMonitor.Discontinuity("live queue reset (seek or skip)");
	}
	m_pulldownResetRequested.store(true, std::memory_order_release);
	BeginQueueGeneration("live queue reset");
	m_sceneDetectorGeneration.fetch_add(1, std::memory_order_acq_rel);
}


void LibplaceboVideoRenderer::SetPostStallResetTelemetrySuppressedUntil(
	uint64_t tick)
{
	if (!m_impl)
		return;
	uint64_t observed = m_impl->postStallResetTelemetrySuppressUntilTick.load(
		std::memory_order_acquire);
	while (observed < tick &&
		!m_impl->postStallResetTelemetrySuppressUntilTick.compare_exchange_weak(
			observed, tick, std::memory_order_release,
			std::memory_order_acquire))
	{
	}
}


void LibplaceboVideoRenderer::SetSceneAwareTimingCorrection(bool enabled)
{
	const bool previous = m_sceneDetectionEnabled.exchange(enabled, std::memory_order_acq_rel);
	if (previous != enabled)
	{
		m_sceneDetectorGeneration.fetch_add(1, std::memory_order_acq_rel);
		m_sceneDetectionStatus.store(
			static_cast<int>(enabled ? SceneDetectorStatus::Warming : SceneDetectorStatus::Disabled),
			std::memory_order_release);
		m_sceneTimingRatesCompatible.store(false, std::memory_order_release);
		m_sceneCorrectionPlanned.store(false, std::memory_order_release);
		m_scenePredictedAction.store(0, std::memory_order_release);
		m_sceneSecondsUntilCorrection.store(0.0, std::memory_order_release);
		m_sceneSecondsUntilPlan.store(0.0, std::memory_order_release);
		m_sceneTimingStatus.store(
			static_cast<int>(enabled
				? AlphaCadenceTimingStatus::WaitingForDxgi
				: AlphaCadenceTimingStatus::Disabled),
			std::memory_order_release);
		m_sceneTimingRateSamples.store(0, std::memory_order_release);
		m_sceneTimingMismatchPpm.store(0.0, std::memory_order_release);
		m_sceneCorrectionDueState.store(0, std::memory_order_release);
		DebugLog::Log("libplacebo scene detection %s", enabled ? "enabled" : "disabled");
	}
}

