bool LibplaceboVideoRenderer::GetOutputModeInfo(CString& details) const
{
	if (!m_impl)
	{
		details.Empty();
		return false;
	}

	std::unique_lock<std::mutex> guard(
		m_impl->renderMutex, std::try_to_lock);
	if (!guard.owns_lock())
		return false;
	auto requestPresentation = [](LibplaceboOutput::PresentationRequest value)
	{
		switch (value)
		{
		case LibplaceboOutput::PresentationRequest::COMPOSED: return "C";
		case LibplaceboOutput::PresentationRequest::DIRECT: return "D";
		default: return "A";
		}
	};
	auto requestRange = [](LibplaceboOutput::RangeRequest value)
	{
		switch (value)
		{
		case LibplaceboOutput::RangeRequest::FULL: return "F";
		case LibplaceboOutput::RangeRequest::LIMITED: return "L";
		default: return "A";
		}
	};
	auto actualPresentation = [](LibplaceboOutput::PresentationModel value)
	{
		switch (value)
		{
		case LibplaceboOutput::PresentationModel::BITBLT: return "Blt";
		case LibplaceboOutput::PresentationModel::FLIP: return "Flip";
		default: return "?";
		}
	};
	CStringA value;
	const std::string signalStatus = m_impl->nvidiaBt2020Reporter.Status();
	const char* outputSignal = signalStatus.c_str();
	const char* outputTarget = m_impl->TargetIsBt2020() ? "SDR BT.2020" :
		(m_impl->TargetIsP3D65() ? "SDR P3-D65 / display manual" : "SDR Rec.709");
	value.Format(
		"Target %s | Req %s/%s/%s/%s -> %s/%s/%s/%s",
		outputTarget,
		requestPresentation(m_impl->outputPlan.request.presentation),
		requestRange(m_impl->outputPlan.request.range),
		LibplaceboOutput::ToString(m_impl->outputPlan.request.gamma),
		LibplaceboOutput::ToString(m_impl->outputPlan.request.primaries),
		actualPresentation(m_impl->actualOutput.presentationModel),
		m_impl->actualOutput.safeToRender
			? (std::string(LibplaceboOutput::ToRangeString(
				m_impl->actualOutput.encoding)) == "FULL" ? "F" : "L")
			: "?",
		m_impl->actualOutput.safeToRender
			? LibplaceboOutput::ToGammaString(m_impl->actualOutput.encoding)
			: "?",
		m_impl->actualOutput.safeToRender &&
			(m_impl->actualOutput.encoding ==
				LibplaceboOutput::DxgiEncoding::FULL_G22_P2020 ||
			 m_impl->actualOutput.encoding ==
				LibplaceboOutput::DxgiEncoding::STUDIO_G22_P2020 ||
			 m_impl->actualOutput.encoding ==
				LibplaceboOutput::DxgiEncoding::STUDIO_G24_P2020)
				? "2020" : "709");
	CStringA gammaAdjustment;
	CStringA outputStatus;
	if (!m_impl->actualOutput.safeToRender)
	{
		outputStatus.Format("Blocked: %s", m_impl->actualOutput.reason.c_str());
	}
	else if (!m_impl->actualOutput.requestedEncodingActive)
	{
		const auto requestedGamma = m_impl->outputPlan.request.gamma;
		if (requestedGamma != LibplaceboOutput::GammaRequest::AUTO &&
			requestedGamma != LibplaceboOutput::GammaRequest::SRGB &&
			m_impl->actualOutput.encoding ==
				LibplaceboOutput::DxgiEncoding::FULL_G22_P709)
		{
			gammaAdjustment.Format("%s req -> sRGB (Windows)",
				LibplaceboOutput::ToString(requestedGamma));
		}
		else
		{
			outputStatus = "Windows-compatible RGB active";
		}
	}
	if (m_impl->activeSettings.diagnosticVpOwnedDxgiPresenter &&
		m_impl->swapchainBlit)
	{
		if (!outputStatus.IsEmpty()) outputStatus += "; ";
		outputStatus += "Composed presentation active";
	}
	if (!gammaAdjustment.IsEmpty())
	{
		value += " | GAMMA: ";
		value += gammaAdjustment;
	}
	if (!outputStatus.IsEmpty())
	{
		value += " | STATUS: ";
		value += outputStatus;
	}
	value += " | SIGNAL: ";
	value += outputSignal;
	value += " | SWAPCHAIN: ";
	switch (m_impl->negotiatedSwapchainFormat)
	{
	case DXGI_FORMAT_R10G10B10A2_UNORM:
		value += "10-bit R10G10B10A2";
		break;
	case DXGI_FORMAT_R16G16B16A16_FLOAT:
		value += "16-bit float RGBA";
		break;
	case DXGI_FORMAT_B8G8R8A8_UNORM:
		value += "8-bit BGRA8";
		break;
	case DXGI_FORMAT_R8G8B8A8_UNORM:
		value += "8-bit RGBA8";
		break;
	default:
		value += "Unknown";
		break;
	}
	value += " | PRESENTER: ";
	value += m_impl->vpOwnedSwapchain ? "VP" : "libplacebo";
	value += " | CONTRACT: ";
	if (!m_impl->actualOutput.safeToRender)
		value += "Blocked";
	else if (!m_impl->actualOutput.requestedEncodingActive)
		value += "Fallback";
	else if (m_impl->vpOwnedSwapchain && m_impl->vpOwnedColorSpaceVerified)
		value += "Active (verified)";
	else
		value += "Active";
	if (m_impl->actualOutput.safeToRender &&
		m_impl->actualOutput.targetTransfer !=
			LibplaceboOutput::TargetTransfer::SWAPCHAIN)
	{
		value += " | DISPLAY: ";
		value += LibplaceboOutput::ToString(
			m_impl->actualOutput.targetTransfer);
	}
	if (!m_impl->lastSdrGammaDecision.reason.empty())
	{
		CStringA gamma;
		gamma.Format(" | SDR Gamma %s: %s (%s->%s; target %s)",
			LibplaceboOutput::ToString(
				m_impl->lastSdrGammaDecision.requested),
			LibplaceboOutput::ToString(
				m_impl->lastSdrGammaDecision.action),
			LibplaceboOutput::ToString(
				m_impl->lastSdrGammaDecision.declaredSource),
			LibplaceboOutput::ToString(
				m_impl->lastSdrGammaDecision.effectiveSource),
			LibplaceboOutput::ToString(
				m_impl->lastSdrGammaDecision.actualTarget));
		value += gamma;
	}
	details = CString(value);
	return true;
}


bool LibplaceboVideoRenderer::GetOutputContractStatus(
	RendererOutputContract::Status& status) const
{
	status = {};
	if (!m_impl)
		return false;

	using namespace RendererOutputContract;
	std::unique_lock<std::mutex> guard(
		m_impl->renderMutex, std::try_to_lock);
	if (!guard.owns_lock())
		return false;
    status.available = true;
    status.calibrationStatusAvailable = m_impl->calibrationStatusAvailable;
    status.calibrationLutAttached = m_impl->calibrationLutAttached && m_impl->displayLutParsed && m_impl->displayLut;
    status.calibrationConfigIdentity = m_impl->activeSettings.configurationIdentity;
    status.calibrationConfigPath = m_impl->activeSettings.configurationPath;
	status.safeToRender = m_impl->actualOutput.safeToRender;
	status.requestedContractActive =
		m_impl->actualOutput.requestedEncodingActive;
	status.vpOwnsPresentation = m_impl->vpOwnedSwapchain != nullptr;
	status.dxgiAppliedVerified = status.vpOwnsPresentation &&
		m_impl->vpOwnedColorSpaceVerified;
	status.strictContract = m_impl->outputPlan.strictContract;
	status.successfulPresents = m_impl->successfulPresentCount;
	status.rendererContent = !m_impl->diagnosticReadbackComplete ?
		RendererOutputContract::RendererContentEvidence::UNKNOWN :
		m_impl->diagnosticReadbackNonBlack ?
			RendererOutputContract::RendererContentEvidence::NONBLACK :
			RendererOutputContract::RendererContentEvidence::ALL_BLACK;
	const AlphaPresentationSnapshot presentationSnapshot =
		m_impl->presentationTelemetry.Snapshot();
	status.displayDelivery = presentationSnapshot.lastPresentedSequence > 0 ?
		RendererOutputContract::DisplayDeliveryEvidence::PRESENTED :
		m_impl->successfulPresentCount > 0 ?
			RendererOutputContract::DisplayDeliveryEvidence::SUBMITTED :
			RendererOutputContract::DisplayDeliveryEvidence::UNKNOWN;
	status.swapchainBitDepth =
		m_impl->negotiatedSwapchainFormat == DXGI_FORMAT_R10G10B10A2_UNORM ? 10 :
		m_impl->negotiatedSwapchainFormat == DXGI_FORMAT_R16G16B16A16_FLOAT ? 16 :
		m_impl->negotiatedSwapchainFormat == DXGI_FORMAT_B8G8R8A8_UNORM ||
		m_impl->negotiatedSwapchainFormat == DXGI_FORMAT_R8G8B8A8_UNORM ? 8 : 0;
	status.presentation = m_impl->actualOutput.presentationModel ==
		LibplaceboOutput::PresentationModel::FLIP ? Presentation::FLIP :
		m_impl->actualOutput.presentationModel ==
		LibplaceboOutput::PresentationModel::BITBLT ? Presentation::BITBLT :
		Presentation::UNKNOWN;
	status.range = std::string(LibplaceboOutput::ToRangeString(
		m_impl->actualOutput.encoding)) == "FULL" ? Range::FULL : Range::LIMITED;
	const pl_color_transfer transfer = m_impl->ResolvedPixelTransfer(
		m_impl->actualOutput.encoding, m_impl->actualOutput.targetTransfer);
	switch (transfer)
	{
	case PL_COLOR_TRC_SRGB: status.transfer = Transfer::SRGB; break;
	case PL_COLOR_TRC_BT_1886: status.transfer = Transfer::BT1886; break;
	case PL_COLOR_TRC_GAMMA18: status.transfer = Transfer::GAMMA18; break;
	case PL_COLOR_TRC_GAMMA20: status.transfer = Transfer::GAMMA20; break;
	case PL_COLOR_TRC_GAMMA22: status.transfer = Transfer::GAMMA22; break;
	case PL_COLOR_TRC_GAMMA24: status.transfer = Transfer::GAMMA24; break;
	case PL_COLOR_TRC_GAMMA26: status.transfer = Transfer::GAMMA26; break;
	case PL_COLOR_TRC_GAMMA28: status.transfer = Transfer::GAMMA28; break;
	default: status.transfer = Transfer::UNKNOWN; break;
	}
	status.primaries = m_impl->TargetIsBt2020() ? Primaries::BT2020 :
		m_impl->TargetIsP3D65() ? Primaries::P3_D65 : Primaries::REC709;
	status.dxgiDeclaration = LibplaceboOutput::ToString(
		m_impl->actualOutput.encoding);
	status.swapchainFormat =
		m_impl->negotiatedSwapchainFormat == DXGI_FORMAT_R10G10B10A2_UNORM ?
			"R10G10B10A2_UNORM" :
		m_impl->negotiatedSwapchainFormat == DXGI_FORMAT_R16G16B16A16_FLOAT ?
			"R16G16B16A16_FLOAT" :
		m_impl->negotiatedSwapchainFormat == DXGI_FORMAT_B8G8R8A8_UNORM ?
			"B8G8R8A8_UNORM" :
		m_impl->negotiatedSwapchainFormat == DXGI_FORMAT_R8G8B8A8_UNORM ?
			"R8G8B8A8_UNORM" : "UNKNOWN";
	status.reason = m_impl->actualOutput.reason;
    const auto& settings = m_impl->activeSettings;
    const auto calibration = LibplaceboOutput::ResolveCalibrationTargetTransfer(
        LibplaceboOutput::ParseGamma(settings.outputGamma),
        Impl::ToSdrTransfer(transfer));
    int ditherDepth = static_cast<int>(status.swapchainBitDepth);
    if (settings.displayBitDepth == "8" || settings.displayBitDepth == "10")
        ditherDepth = (std::min)(ditherDepth, std::stoi(settings.displayBitDepth));
    std::ostringstream summary;
    summary << (status.safeToRender && status.requestedContractActive &&
        !(settings.outputRange == "limited" && status.range != Range::LIMITED) ? "Requested transport active" : "OUTPUT MISMATCH / NOT ACTIVE")
        << ": requested " << settings.outputRange << "/" << settings.outputTransportGamma
        << "; effective " << LibplaceboOutput::ToRangeString(m_impl->actualOutput.encoding)
        << "; carrier " << pl_color_transfer_name(Impl::EncodingTransfer(m_impl->actualOutput.encoding))
        << "; presentation " << (status.presentation == Presentation::FLIP ? "Flip model" :
            status.presentation == Presentation::BITBLT ? "Legacy BitBlt" : "Unknown")
        << (status.range == Range::LIMITED ? "\n" + LibplaceboOutput::DescribeLimitedTransfer(
            m_impl->actualOutput.encoding, m_impl->lastRenderedTargetTransfer,
            status.calibrationStatusAvailable, status.calibrationLutAttached) : "")
        << "\nTarget gamut: " << settings.sdrTargetPrimaries << "; display gamma "
        << LibplaceboOutput::ToString(calibration)
        << (status.calibrationLutAttached ? " (inactive: calibration LUT)" : "")
        << "; SDR input: " << LibplaceboOutput::ToString(m_impl->lastSdrGammaDecision.declaredSource)
        << " -> " << LibplaceboOutput::ToString(m_impl->lastSdrGammaDecision.effectiveSource)
        << "; dither target " << settings.displayBitDepth << " -> " << ditherDepth
        << " bits (surface " << status.swapchainBitDepth << ")"
        << "\nLUT: " << m_impl->displayLutStatus
        << "; SDR LUT input gamma: " << settings.sdrLutInputGamma
        << "; HDR tone-map target gamma: " << settings.hdrToneMapTargetGamma
        << "; BT.2020 signaling: " << m_impl->nvidiaBt2020Reporter.Status()
        << "\n" << status.reason;
    status.uiSummary = summary.str();
	return true;
}

bool LibplaceboVideoRenderer::RequestRenderedOutputCapture(CString& status)
{
	if (!m_impl || m_state.load(std::memory_order_acquire) !=
		RendererState::RENDERSTATE_RENDERING)
	{
		status = TEXT("Rendered-output capture requires an active VP Renderer");
		return false;
	}
	bool expected = false;
	if (!m_impl->renderedOutputCaptureRequested.compare_exchange_strong(
		expected, true, std::memory_order_acq_rel))
	{
		status = TEXT("A rendered-output capture is already queued");
		return false;
	}
	status = TEXT("Rendered-output capture queued (screenshots folder)");
	DebugLog::Log(
		"Rendered-output capture queued: stage=next-rendered-frame output_directory=%ls",
		ScreenshotDirectory().c_str());
	return true;
}


bool LibplaceboVideoRenderer::GetDisplayLutInfo(CString& details) const
{
	if (!m_impl)
	{
		details.Empty();
		return false;
	}

	std::unique_lock<std::mutex> guard(
		m_impl->renderMutex, std::try_to_lock);
	if (!guard.owns_lock())
		return false;
	details = CString(CStringA(m_impl->displayLutStatus.c_str()));
	return true;
}

bool LibplaceboVideoRenderer::GetDetectedPictureAspect(
	DetectedPictureAspect& result) const
{
	result = {};
	if (!m_impl)
		return true;
	std::unique_lock<std::mutex> guard(
		m_impl->renderMutex, std::try_to_lock);
	if (!guard.owns_lock())
		return false;
	result.sourceGeneration = m_impl->activePictureAnalysisSourceGeneration;
	result.publicationGeneration = m_impl->nlsGeometryGeneration;
	const ActivePictureBounds& geometry = m_impl->nlsGeometry;
	if (m_impl->nlsGeometryAvailable &&
		m_impl->nlsGeometrySourceGeneration == result.sourceGeneration &&
		(m_impl->nlsGeometryClassification ==
			ActivePictureClassification::FULL_RASTER_TRUSTED ||
		 m_impl->nlsGeometryClassification ==
			ActivePictureClassification::BAR_CROP_TRUSTED) &&
		geometry.right > geometry.left && geometry.bottom > geometry.top)
	{
		result.ratio = static_cast<double>(geometry.right - geometry.left) /
			(geometry.bottom - geometry.top);
		result.available = std::isfinite(result.ratio) &&
			result.ratio > 0.0;
	}
	return true;
}


bool LibplaceboVideoRenderer::GetVideoIngressInfo(CString& details) const
{
	if (!m_impl)
	{
		details.Empty();
		return false;
	}

	std::lock_guard<std::mutex> guard(m_impl->ingressStatusMutex);
	details = CString(CStringA(m_impl->ingressStatus.c_str()));
	return !details.IsEmpty();
}

bool LibplaceboVideoRenderer::GetRenderLoad(RendererRenderLoad& load) const
{
	load = {};
	if (!m_impl)
		return false;

	// The meter holds its own lock, so unlike the presentation-timing accessor
	// this never contends with renderMutex and cannot be starved by a busy
	// render thread - the OSD would otherwise blank exactly when the machine
	// is under the load being measured.
	load = m_impl->RenderLoadSnapshot();
	// `supported`, not `valid`. The window is deliberately EMPTY during the
	// warm-up guard, so returning `valid` here hid the whole panel for the
	// first seconds after every start, restart and backlog recovery - and hid
	// the `settling` row that exists to explain exactly that gap. The caller
	// reads `settling` and `gpuValid` to decide what to print; whether a
	// sample happens to be in the window is not the caller's question.
	return load.supported;
}


void LibplaceboVideoRenderer::SetRenderLoadDisplayRefreshRate(
	double refreshRateHz)
{
	if (!m_impl)
		return;
	const double validated = std::isfinite(refreshRateHz) &&
		DisplayRefreshBounds::Accepts(refreshRateHz) ?
		refreshRateHz : 0.0;
	m_impl->renderLoadDisplayRefreshHz.store(
		validated, std::memory_order_release);
}


bool LibplaceboVideoRenderer::GetPresentationTargetTiming(
	double& leadMs, double& captureToTargetMs) const
{
	leadMs = m_presentationTargetLeadMs.load(std::memory_order_relaxed);
	captureToTargetMs = m_captureToPresentationTargetMs.load(
		std::memory_order_relaxed);
	return m_presentationTargetTimingKnown.load(std::memory_order_acquire);
}

// RS-232 connection test: stop the LED drive (it restores full light and
// closes the port), unless video is playing; ResumeLedDriveAfterTest starts it
// again from the saved settings.
bool LibplaceboVideoRenderer::GetCalibrationOutput(Calibration::PatternOutputInfo& info) const
{
	info = Calibration::PatternOutputInfo();
	auto setReason = [&info](const char* text) { strncpy_s(info.reason, sizeof(info.reason), text, _TRUNCATE); };
	if (!m_impl || !m_implInitialized.load(std::memory_order_acquire))
	{
		setReason("the VP Renderer is not running (start VP with any source)");
		return false;
	}
	if (m_state.load(std::memory_order_acquire) != RendererState::RENDERSTATE_RENDERING)
	{
		setReason("the VP Renderer is not rendering (start VP with any source)");
		return false;
	}
	// The format fields are render-thread state: read under renderMutex, which
	// the loop releases between refreshes; a cached copy answers when it stays busy.
	bool fresh = false;
	const int attempts = m_impl->calibrationHost.FreshOutputAttempts(m_calibrationPatternActive.load(std::memory_order_acquire));
	for (int attempt = 0; attempt < attempts && !fresh; ++attempt)
	{
		std::unique_lock<std::mutex> guard(m_impl->renderMutex, std::try_to_lock);
		if (!guard.owns_lock())
		{
			if (attempts > 1) Sleep(2);
			continue;
		}
		double hz = m_impl->renderLoadDisplayRefreshHz.load(std::memory_order_acquire);
		if (!(hz > 0.0)) hz = MonitorRefreshHz(m_videoHwnd);
		m_impl->calibrationHost.PublishOutputFacts({ m_impl->negotiatedSwapchainFormat, m_impl->activeSettings.displayBitDepth,
			Impl::EncodingLevels(m_impl->actualOutput.encoding) == PL_COLOR_LEVELS_LIMITED, m_impl->TargetIsBt2020(), hz,
			m_impl->swapchain != nullptr && !m_impl->outputResourcesRetired });
		fresh = true;
	}
	return m_impl->calibrationHost.FillOutputInfo(info, fresh);
}

bool LibplaceboVideoRenderer::SetCalibrationPattern(const Calibration::PatternRequest& request, CString& reason)
{
	reason.Empty();
	if (!m_impl)
	{
		reason = TEXT("the VP Renderer is not running");
		return !request.active;
	}
	if (request.active)
	{
		if (m_state.load(std::memory_order_acquire) != RendererState::RENDERSTATE_RENDERING)
		{
			reason = TEXT("the VP Renderer is not rendering (start VP with any source)");
			return false;
		}
		m_impl->calibrationHost.SetPattern(request);
		if (!m_calibrationPatternActive.load(std::memory_order_acquire))
		{
			// The LED drive stops at full light for the patches (DynamicDriveHost::SuspendForCalibration).
			const bool ledStopped = m_dynamicDrive.SuspendForCalibration(DynamicDriveContext());
			m_impl->calibrationHost.ResetPatternLogs();
			m_calibrationPatternActive.store(true, std::memory_order_release);
			BeginQueueGeneration("calibration patterns");
			DebugLog::Log("Calibration patterns: started (video paused, Dynamic Drive %s)",
				ledStopped ? "stopped at full light" : "not running");
		}
		m_queueChanged.notify_all();
		return true;
	}
	if (!m_calibrationPatternActive.exchange(false, std::memory_order_acq_rel))
		return true;
	m_impl->calibrationHost.EndPattern();
	BeginQueueGeneration("calibration patterns ended");
	m_queueChanged.notify_all();
	m_dynamicDrive.ResumeAfterCalibration(DynamicDriveContext());
	m_impl->ReleaseFallback("calibration patch");   // WP-12: the full-field fallback lasts for the run
	DebugLog::Log("Calibration patterns: ended (video resumes)");
	return true;
}

bool LibplaceboVideoRenderer::SuspendLedDriveForTest(CString& reason)
{
	reason.Empty();
	std::string why;
	const bool suspended = m_dynamicDrive.SuspendForTest(DynamicDriveContext(), why);
	if (!suspended)
		reason = CString(why.c_str());
	return suspended;
}

// Integration 2026-10-17: the forced shutdown's LED stop. The render state lock may be
// held by the blocked retirement, so the module comes from the render loop's atomic copy
// (or the host adapter's when the lock is free at once). Stop() restores full light.
bool LibplaceboVideoRenderer::StopLedDriveForShutdown()
{
	// Only the render side's module copy and a lock that is free at once (never pipelineSlots:
	// the render thread may be rebuilding it while a blocked retirement holds the state lock).
	LedDrive::HostContext context;
	if (m_impl)
		context.frame = &m_impl->dynamicDrive;
	return m_dynamicDrive.StopForShutdown(context);
}

void LibplaceboVideoRenderer::ResumeLedDriveAfterTest()
{
	m_dynamicDrive.ResumeAfterTest(DynamicDriveContext());
}

